package edu.sharespace;

import jakarta.persistence.*;import com.fasterxml.jackson.annotation.JsonIgnore;import java.time.Instant;import java.time.OffsetDateTime;

public final class Domain { private Domain(){} public enum Role{USER,OWNER,ADMIN} public enum BookingStatus{PENDING,APPROVED,REJECTED,WAITLISTED,CHECKED_OUT,RETURN_PENDING_CONFIRMATION,COMPLETED,CANCELLED,OVERDUE} public enum ReportType{BEFORE,AFTER} public enum IncidentType{DAMAGE,DELAY,OTHER} public enum IncidentStatus{OPEN,RESOLVED}
 @Entity @Table(name="app_users",uniqueConstraints=@UniqueConstraint(columnNames="email")) public static class User { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String fullName; @Column(nullable=false,unique=true) public String email; @JsonIgnore @Column(name="firebase_uid",unique=true) public String firebaseUid; @Enumerated(EnumType.STRING) @Column(nullable=false) public Role role=Role.USER; @Column(nullable=false) public String membershipStatus="ACTIVE"; public boolean verified=true; @JsonIgnore @Column(nullable=false) public String training=""; @Column(nullable=false) public Instant createdAt=Instant.now(); protected User(){} public User(String n,String e,Role r){fullName=n;email=e;role=r;} }
 @Entity @Table(name="resources") public static class Resource { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String name; @Column(nullable=false,length=3000) public String description; @Column(nullable=false) public String category; @Column(nullable=false) public String location; @ManyToOne(optional=false) public User owner; @Column(nullable=false) public String status="AVAILABLE"; public boolean requiresTraining; public String requiredTrainingDescription; public boolean requiresApproval=true; public int maxBookingHours=4; @Column(length=2000) public String usageRules; public String imageUrl; @Column(nullable=false) public Instant createdAt=Instant.now(); protected Resource(){} }
 @Entity @Table(name="bookings",indexes=@Index(columnList="resource_id,start_time,end_time")) public static class Booking { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) public Resource resource; @ManyToOne(optional=false) public User requester; @Column(name="start_time",nullable=false) public OffsetDateTime startTime; @Column(name="end_time",nullable=false) public OffsetDateTime endTime; @Column(nullable=false,length=1000) public String purpose; @Enumerated(EnumType.STRING) @Column(nullable=false) public BookingStatus status=BookingStatus.PENDING; @Column(nullable=false) public String eligibilityStatus="ELIGIBLE"; public String decisionReason; @ManyToOne public User approvedBy; public Instant checkedInAt; public Instant returnedAt; @Column(nullable=false) public Instant createdAt=Instant.now(); }
 @Entity @Table(name="condition_reports",uniqueConstraints={@UniqueConstraint(columnNames={"booking_id","report_type"})}) public static class ConditionReport { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) public Booking booking; @Enumerated(EnumType.STRING) @Column(nullable=false) public ReportType reportType; @Column(nullable=false,length=2000) public String description; public String imageUrl; @ManyToOne(optional=false) public User reportedBy; @Column(nullable=false) public Instant createdAt=Instant.now(); }
 @Entity @Table(name="incidents") public static class Incident { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) public Booking booking; @Enumerated(EnumType.STRING) @Column(nullable=false) public IncidentType type; @Column(nullable=false,length=2000) public String description; @Enumerated(EnumType.STRING) @Column(nullable=false) public IncidentStatus status=IncidentStatus.OPEN; public String resolutionNote; @ManyToOne(optional=false) public User reportedBy; @ManyToOne public User reviewedBy; @Column(nullable=false) public Instant createdAt=Instant.now(); public Instant resolvedAt; }
 @Entity @Table(name="audit_events") public static class AuditEvent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @ManyToOne(optional=false) public User actor; @Column(nullable=false) public String action; @Column(nullable=false) public String entityType; @Column(nullable=false) public Long entityId; @Column(length=2000) public String reason; @Column(nullable=false) public Instant timestamp=Instant.now(); }
}
